const СВГ = (тело, цвет) => '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="96" height="96" '
  + 'fill="none" stroke="' + цвет + '" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + тело + '</svg>';
const ВАДРЕС = свг => 'data:image/svg+xml,' + encodeURIComponent(свг);

function Показать(){
  const п = параметры({});
  const искать = String(п.искать || '').trim().toLowerCase();
  const цвет = п.цвет || '#14171c';
  const имена = Object.keys(НАБОР).filter(и => !искать || и.indexOf(искать) >= 0);
  панель.список('значки', имена.map(и => ({имя: и, картинка: ВАДРЕС(СВГ(НАБОР[и], цвет))})));
  панель.поле('сколько', имена.length + ' из ' + Object.keys(НАБОР).length);
}

function Старт(){ Показать(); }

function Вставить(){
  const п = параметры({});
  const имя = п.значки;
  if(!имя || !НАБОР[имя]){ панель.сообщение('Сначала выберите значок в сетке'); return; }
  const в = книга.выделение;
  const бок = Math.max(8, Math.min(600, +п.размер || 48));
  картинка.вставить(СВГ(НАБОР[имя], п.цвет || '#14171c'),
    {адрес: в.адрес, ширина: бок, высота: бок, имя: 'Значок «' + имя + '»'});
  панель.сообщение('Значок «' + имя + '» положен на ' + в.адрес);
}

/* Вся сетка разом — удобно посмотреть набор целиком */
function Всё(){
  const п = параметры({}), в = книга.выделение;
  const бок = Math.max(8, Math.min(600, +п.размер || 48));
  const имена = Object.keys(НАБОР);
  const вРяду = 6;
  имена.forEach((и, к) => {
    картинка.вставить(СВГ(НАБОР[и], п.цвет || '#14171c'), {
      строка: в.строка + Math.floor(к / вРяду), столбец: в.столбец + (к % вРяду),
      адрес: адресКлетки(в.строка + Math.floor(к / вРяду), в.столбец + (к % вРяду)),
      ширина: бок, высота: бок, имя: и});
  });
  панель.сообщение('Положено значков: ' + имена.length);
}

function адресКлетки(строка, столбец){
  let имя = '', с = столбец;
  while(с > 0){ const о = (с - 1) % 26; имя = String.fromCharCode(65 + о) + имя; с = (с - о - 1) / 26; }
  return имя + строка;
}
